production.solution:
const groups = {};
for (const item of $input.all()) {
  const emp = item.json.employee_id;
  const amt = Number(item.json.amount);
  if (!groups[emp]) groups[emp] = 0;
  groups[emp] += amt;
}

const out = [];
for (const emp in groups) {
  out.push({ json: { employee_id: emp, total: groups[emp] } });
}
return out;
